import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label, FormGroup } from 'reactstrap';
import Select from 'react-select';
import CustomButton from '../../../../components/CustomButton';
import { employeeStatic } from '../../../../config/constants';
import { formEmpSelectList, formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import { fetchTeacherBySubjectApi } from 'actions/admin/subjects';
import {
  fetchEmpAssignSubjectApi,
  saveEmpAssignSubjectService,
  updateEmpAssignSubjectService,
} from 'actions/admin/employees';

// Per-subject "who teaches this" modal, opened from a row on the Subjects page. Unlike
// EmpSubjectAssignModal (Employee page, teacher-centric: pick a teacher then multi-select
// their subjects), this is subject-centric: the subject is fixed, pick the one teacher for
// it. It's built on the same two assign/update endpoints EmpSubjectAssignModal already
// uses, just fed a single-subject payload instead of the teacher's whole subject list.
//
// The picker lists every school teacher (not just unassigned ones) - a teacher can teach
// more than one subject, so being assigned elsewhere should never make them unpickable
// here. "Who's still free" lives separately on the Subjects page itself.
const AssignTeacherSubjectModal = ({ isOpen, subject, allTeachers, token, onClose, onSuccess, showWarning }) => {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [currentTeacherSubjectId, setCurrentTeacherSubjectId] = useState(null);
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [initialTeacherId, setInitialTeacherId] = useState(null);

  const teacherOptions = formEmpSelectList(allTeachers) || [];

  useEffect(() => {
    if (isOpen && subject) {
      const { batchId } = getGlobalCurrentBatchUtils();
      setLoading(true);
      setSelectedTeacher(null);
      setCurrentTeacherSubjectId(null);
      setInitialTeacherId(null);
      fetchTeacherBySubjectApi({ subjectId: subject.subjectId, token })
        .then(teacherRes => {
          const currentTeacher = teacherRes?.data;
          if (currentTeacher?.employeeId) {
            const currentOption =
              teacherOptions.find(el => el.employeeId === currentTeacher.employeeId) ||
              formEmpSelectList([currentTeacher])[0];
            setSelectedTeacher(currentOption);
            setInitialTeacherId(currentTeacher.employeeId);
            fetchEmpAssignSubjectApi({ employeeId: currentTeacher.employeeId, batchId, token }).then(res => {
              const match = res?.data?.find(el => el.subjectId === subject.subjectId);
              setCurrentTeacherSubjectId(match?.teacherSubjectId || null);
            });
          }
        })
        .catch(err => showWarning(formResMessage(err), 'error'))
        .finally(() => setLoading(false));
    }
  }, [isOpen, subject]);

  const handleSubmit = e => {
    e.preventDefault();
    if (!selectedTeacher) return;
    const globalSchool = getGlobalSchoolUtils();
    setSaving(true);
    const postData = {
      employeeId: selectedTeacher.employeeId,
      schoolId: globalSchool.schoolId,
      subjects: [
        {
          subjectId: subject.subjectId,
          ...(initialTeacherId === selectedTeacher.employeeId && currentTeacherSubjectId
            ? { teacherSubjectId: currentTeacherSubjectId }
            : {}),
        },
      ],
    };
    const isUpdate = initialTeacherId === selectedTeacher.employeeId && currentTeacherSubjectId;
    const request = isUpdate
      ? updateEmpAssignSubjectService({ postData, token })
      : saveEmpAssignSubjectService({ postData, token });
    request()
      .then(() => {
        setSaving(false);
        onSuccess();
      })
      .catch(err => {
        setSaving(false);
        showWarning(formResMessage(err), 'error');
      });
  };

  return (
    <Modal size="md" isOpen={isOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>Assign {employeeStatic}</ModalHeader>
        <ModalBody>
          <div className="container-fluid">
            <Row>
              <Col sm={12}>
                <FormGroup>
                  <Label>Subject</Label>
                  <div style={{ fontWeight: 'bold' }}>
                    {subject?.name} <span style={{ color: '#98a2ad' }}>({subject?.subjectCode})</span>
                  </div>
                </FormGroup>
              </Col>
              <Col sm={12}>
                <FormGroup>
                  <Label htmlFor="">
                    {employeeStatic}
                    <sup> *</sup>
                  </Label>
                  <Select
                    isLoading={loading}
                    isClearable
                    value={selectedTeacher}
                    onChange={value => setSelectedTeacher(value)}
                    options={teacherOptions}
                    placeholder={`Select ${employeeStatic.toLowerCase()}...`}
                  />
                </FormGroup>
              </Col>
            </Row>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={saving || loading || !selectedTeacher} loading={saving} name="Save" />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default AssignTeacherSubjectModal;
