import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import { subjectTableHead } from 'variables/general';
import {
  fetchAllSubjectsService,
  saveSubjectService,
  fetchSubjectService,
  updateSubjectService,
  deleteSubjectService,
  fetchCourseSubjectsService,
} from 'actions/admin/subjects';
import { fetchGenSubjectAndCodesService } from 'actions/admin/config';
import { fetchBatchCourseService } from 'actions/admin/courses';
import { fetchSchoolEmployeesApi, fetchAllEmpAssignSubjectsService } from 'actions/admin/employees';
import { fetchUnassignedTeachersApi } from 'actions/admin/subjects';
import { store } from 'index';
import SubjectFormModal from './components/SubjectFormModal.jsx';
import {
  formCourseSelectList,
  formResMessage,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
} from '../../../utils/commonFunc.js';
import { showToast } from '../../../actions/admin/auth.js';
import constants, { courseStatic, coursesStatic, employeeStatic } from '../../../config/constants.js';
import MuiTable from '../Common/MuiTable.jsx';
import CommonSelect from 'components/CustomSelect';
import Radio from '@material-ui/core/Radio';
import Tabs from '@material-ui/core/Tabs';
import Tab from '@material-ui/core/Tab';
import colors from 'config/colors';
import CustomButton from '../../../components/CustomButton';
import AssignTeacherSubjectModal from './components/AssignTeacherSubjectModal.jsx';

const STUDY_LEVEL_TABS = [
  { value: 'PRIMARY', label: 'Primary' },
  { value: 'SECONDARY', label: 'Secondary' },
  { value: 'HIGHER_SECONDARY', label: 'Higher Secondary' },
  { value: 'GENERAL', label: 'General' },
];

// Admins manage the subjects (add, edit, assign a teacher). A teacher sees the same lists but can change nothing:
// no add / edit / assign controls, no dialogs, and no list of teachers still without a subject (an admin's to-do).
// This hides the controls only - the backend does not check the role on these endpoints.
class SubjectPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: null,
      isModalOpen: false,
      // The "SCHOOL SUBJECTS" view groups subjects into Primary/Secondary/Higher Secondary
      // tabs client-side, so it needs the full list up front rather than one server page
      // at a time - a page-sized slice would show an incomplete, shifting set per tab.
      pageParams: {
        page: 1,
        size: 500,
      },
      fetchSubjectType: 'courseSubject',
      courseId: null,
      subjectsFetching: false,
      courseSubjectsFetching: false,
      schoolSubjectLevel: 'PRIMARY',
      isAssignTeacherModalOpen: false,
      assignTeacherSubject: null,
      unassignedTeachers: [],
      unassignedTeachersFetching: false,
      // Fetched into local state, not the shared state.employees.employeeList redux slice -
      // Staff Attendance/Teacher Subjects/Reports etc. all write into that same slot with
      // whatever profession they last fetched, so reading it here after visiting one of those
      // pages could silently show workers in what's meant to be a teachers-only list.
      employees: [],
    };
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  isReadOnly = () => this.props.loggedUserRole === constants.roles.teacher;

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId });
      this.fetchGenSubjectAndCodes(globalSchool);
      this.fetchBatchClassAndSubjects();
      fetchSchoolEmployeesApi({
        schoolId: globalSchool.schoolId,
        token: this.props.loggedUserToken,
        profession: 'TEACHING',
      }).then(employees => this.setState({ employees: employees || [] }));
      if (!this.props.empAssignSubjectList?.length) {
        this.props.fetchAllEmpAssignSubjects({
          schoolId: globalSchool.schoolId,
          token: this.props.loggedUserToken,
        });
      }
      if (!this.isReadOnly()) {
        this.fetchUnassignedTeachers(globalSchool);
      }
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  // Who currently has zero subjects at all - shown on the page itself (not inside the
  // assign modal) so an admin can see who's fully free at a glance while assigning.
  fetchUnassignedTeachers = (globalSchool = getGlobalSchoolUtils()) => {
    this.setState({ unassignedTeachersFetching: true });
    fetchUnassignedTeachersApi({ schoolId: globalSchool.schoolId, token: this.props.loggedUserToken })
      .then(res => this.setState({ unassignedTeachers: res?.data || [] }))
      .catch(err => this.showWarning(formResMessage(err), 'error'))
      .finally(() => this.setState({ unassignedTeachersFetching: false }));
  };

  fetchGenSubjectAndCodes = (globalSchool = getGlobalSchoolUtils(), refetchAgain) => {
    if (!this.props?.subjectCodes?.length || refetchAgain) {
      this.props.fetchGenSubjectAndCodes({
        schoolId: globalSchool.schoolId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchCourseSubjects = async (courseId, canFetchAgain) => {
    if (!this.state.courseId || this.state.courseId !== courseId || (courseId && canFetchAgain)) {
      this.isLoading('courseSubjectsFetching', true);
      await this.props.fetchCourseSubjects({
        courseId,
        token: this.props.loggedUserToken,
      });
      this.isLoading('courseSubjectsFetching', false);
    }
  };

  fetchBatchClassAndSubjects = async (canFetchAgain, passCourseId) => {
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId: stateCourseId } = this.state;
    if (batchId) {
      let courseList = [];
      if (!stateCourseId) {
        courseList =
          !this.props.batchCourseList?.length || canFetchAgain
            ? await this.props.fetchBatchCourses({
                schoolId: globalSchool.schoolId,
                batchId,
                token: this.props.loggedUserToken,
              })
            : this.props.batchCourseList;
      }
      if (passCourseId || courseList?.length || stateCourseId || canFetchAgain) {
        const courseId = passCourseId || stateCourseId || courseList?.[0]?.courseId;
        this.fetchCourseSubjects(courseId, canFetchAgain);
        if (!passCourseId && !stateCourseId && courseId) {
          this.setState({ courseId });
        }
      }
    }
  };

  fetchAllSubjects = async canFetchAgain => {
    const { loggedUserId, loggedUserToken, subjectData } = this.props;
    const { batchId } = getGlobalCurrentBatchUtils();
    if (this.state.schoolId && batchId && (!subjectData?.content?.length || canFetchAgain)) {
      this.isLoading('subjectsFetching', true);
      await this.props.fetchAllSubjects({
        schoolId: this.state.schoolId,
        adminId: loggedUserId,
        batchId,
        token: loggedUserToken,
        pageParams: this.state.pageParams,
      });
      this.isLoading('subjectsFetching', false);
    }
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  openAssignTeacherModal = subject => this.setState({ isAssignTeacherModalOpen: true, assignTeacherSubject: subject });

  closeAssignTeacherModal = () => this.setState({ isAssignTeacherModalOpen: false, assignTeacherSubject: null });

  assignTeacherSuccess = () => {
    this.closeAssignTeacherModal();
    this.showWarning(`${employeeStatic} assigned successfully`, 'success');
    const globalSchool = getGlobalSchoolUtils();
    this.props.fetchAllEmpAssignSubjects({ schoolId: globalSchool.schoolId, token: this.props.loggedUserToken });
    this.fetchUnassignedTeachers(globalSchool);
  };

  saveSubject = data => {
    const { loggedUserId, loggedUserToken } = this.props;
    return this.props.saveSubject({
      courseId: data?.course?.courseId,
      postData: data?.subjectList,
      adminId: loggedUserId,
      token: loggedUserToken,
    });
  };

  fetchSubject = subjectId => {
    return this.props.fetchSubject({ subjectId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateSubject = data => {
    return this.props.updateSubject({
      subjectId: data.subjectId,
      postData: data,
      adminId: this.props.loggedUserId,
      token: this.props.loggedUserToken,
    });
  };

  subjectUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Subject added successfully' : 'Subject Updated successfully', 'success');
    this.fetchSubjectOnSwitch(true);
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteSubject = subjectId => {
    return this.props
      .deleteSubject({ subjectId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchSubjectOnSwitch(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    if (page !== this.state.pageParams.page) {
      this.setState(
        {
          pageParams: {
            ...this.state.pageParams,
            page,
          },
        },
        () => {
          this.fetchSubjectOnSwitch(true);
        }
      );
    }
  };

  fetchSubjectOnSwitch = (canFetchAgain, val = this.state.fetchSubjectType) => {
    if (val === 'schoolSubject') {
      this.fetchAllSubjects(canFetchAgain);
    } else if (val === 'courseSubject') {
      this.fetchBatchClassAndSubjects(canFetchAgain);
    }
  };

  handleCheckChange = val => {
    this.setState(prevState => ({
      ...prevState,
      fetchSubjectType: val,
    }));
    this.fetchSubjectOnSwitch(false, val);
  };

  handleSelectChange = selectItem => {
    if (!this.state.courseId || selectItem.value !== this.state.courseId) {
      this.setState(prevState => ({
        ...prevState,
        courseId: selectItem.value,
      }));
      this.fetchBatchClassAndSubjects(true, selectItem.value);
    }
  };

  // subjectId -> assigned teacher (raw employee record), flattened from the school-wide
  // teacher/subject assignment list. Built here rather than stored, since it's cheap and
  // only needed for display.
  getSubjectTeacherMap = () => {
    const { empAssignSubjectList = [] } = this.props;
    const { employees = [] } = this.state;
    const employeeById = employees.reduce((acc, emp) => {
      acc[emp.employeeId] = emp;
      return acc;
    }, {});
    return empAssignSubjectList.reduce((acc, teacherAssign) => {
      const emp = employeeById[teacherAssign.employeeId];
      (teacherAssign.subjects || []).forEach(subjectAssign => {
        acc[subjectAssign.subjectId] = emp;
      });
      return acc;
    }, {});
  };

  render() {
    const {
      isModalOpen,
      fetchSubjectType,
      courseId,
      subjectsFetching,
      schoolSubjectLevel,
      isAssignTeacherModalOpen,
      assignTeacherSubject,
      unassignedTeachers,
      unassignedTeachersFetching,
      employees,
    } = this.state;
    // const batchData = getGlobalCurrentBatchUtils();
    const {
      batchCourseList,
      courseSubjects,
      subjectData,
      subject,
      subjectCodes,
      // currentBatch = batchData,
      // test
    } = this.props;

    const subjectTeacherMap = this.getSubjectTeacherMap();
    const readOnly = this.isReadOnly();

    let subjects = [];
    if (fetchSubjectType === 'schoolSubject') {
      const allSchoolSubjects = subjectData?.content?.length > 0 ? subjectData.content : [];
      subjects = allSchoolSubjects.filter(el => (el.course?.studyLevel || 'GENERAL') === schoolSubjectLevel);
    } else {
      subjects = courseSubjects || [];
    }

    const choiceCard = (checked, label, description, onClick) => (
      <div
        onClick={onClick}
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 4,
          padding: '8px 12px',
          borderRadius: 8,
          border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
          backgroundColor: checked ? '#F5EDFB' : '#fff',
          cursor: 'pointer',
        }}>
        <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2, marginTop: -2 }} />
        <div>
          <div style={{ fontWeight: 'bold', fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{description}</div>
        </div>
      </div>
    );

    const subjectFilter = () => {
      return (
        <>
          <Col sm={4} md={3} lg={3} className="mb-2">
            {choiceCard(
              fetchSubjectType === 'courseSubject',
              `${courseStatic.toUpperCase()} SUBJECTS`,
              `These are the assigned subject list for selected ${courseStatic.toLowerCase()}`,
              () => this.handleCheckChange('courseSubject')
            )}
          </Col>
          <Col sm={4} md={4} lg={4} className="mb-2">
            {choiceCard(
              fetchSubjectType === 'schoolSubject',
              'SCHOOL SUBJECTS',
              `This section is just to show the School Subjects. These are the subjects that already been assigned to the ${coursesStatic}. Please click ${courseStatic.toUpperCase()} SUBJECTS button to assign a new subject for selected ${courseStatic}`,
              () => this.handleCheckChange('schoolSubject')
            )}
          </Col>
          {!readOnly && (
            <Col sm={4} md={4} lg={4} className="mb-2">
              {choiceCard(
                fetchSubjectType === 'availableTeachers',
                `UNASSIGNED ${employeeStatic.toUpperCase()}S`,
                `${employeeStatic}s not yet assigned to any subject, so you can see at a glance who still needs one`,
                () => this.handleCheckChange('availableTeachers')
              )}
            </Col>
          )}
        </>
      );
    };

    const courseArr = formCourseSelectList(batchCourseList);

    const filterSelect = () => {
      if (fetchSubjectType === 'courseSubject') {
        return (
          <Row>
            <Col sm={12} md={6} lg={6} className="mb-2">
              <CommonSelect
                name="courseId"
                noLabel={true}
                value={courseId}
                onChange={(name, value) => {
                  this.handleSelectChange({ value });
                }}
                options={courseArr}
                applyLabelStyle={true}
                placeholder={`Select ${courseStatic}`}
              />
            </Col>
          </Row>
        );
      }
      return null;
    };

    return (
      <div className="content">
        <Row>{subjectFilter()}</Row>
        {filterSelect()}
        {fetchSubjectType === 'schoolSubject' && (
          <Tabs
            value={schoolSubjectLevel}
            onChange={(e, val) => this.setState({ schoolSubjectLevel: val })}
            indicatorColor="primary"
            textColor="primary"
            variant="scrollable"
            scrollButtons="auto"
            className="mb-2">
            {STUDY_LEVEL_TABS.map(lvl => (
              <Tab key={lvl.value} value={lvl.value} label={lvl.label} />
            ))}
          </Tabs>
        )}
        {fetchSubjectType === 'courseSubject' && !readOnly && (
          <Row>
            <Col sm={12} className="mb-2 text-right">
              <CustomButton onClick={this.formModalOpen} name="Assign Class Subject" />
            </Col>
          </Row>
        )}
        {fetchSubjectType === 'availableTeachers' ? (
          <MuiTable
            tableHeaders={[employeeStatic, 'Code']}
            tableBodyData={{ content: unassignedTeachers }}
            bodyColumns={['name', 'code']}
            idName="employeeId"
            hidePagination
            isLoading={unassignedTeachersFetching}
          />
        ) : (
          <MuiTable
            // The class column only earns its place in SCHOOL SUBJECTS, where a row can
            // belong to any class - in CLASS SUBJECTS every row is already scoped to the
            // one class picked above, so repeating it on every row is just noise.
            tableHeaders={(fetchSubjectType === 'schoolSubject'
              ? subjectTableHead
              : ['Subject & Code', `Assigned ${employeeStatic}`, 'Action']
            ).filter(head => !(readOnly && head === 'Action'))}
            tableBodyData={{
              ...subjectData,
              content: subjects.map(el => {
                const codeSpan = code => <span style={{ color: '#bcbcbc', fontWeight: 'bold' }}> ({code})</span>;
                const assignedTeacher = subjectTeacherMap[el.subjectId];
                return {
                  ...el,
                  subjectCode: el.subjectCode,
                  nameAndCode: (
                    <>
                      {el.name} {codeSpan(el.subjectCode)}
                    </>
                  ),
                  assignedTeacherName: assignedTeacher ? (
                    <>
                      {assignedTeacher.name} {assignedTeacher.code && codeSpan(assignedTeacher.code)}
                    </>
                  ) : (
                    <span style={{ color: '#bcbcbc', fontStyle: 'italic' }}>Unassigned</span>
                  ),
                  courseName: el.course.name,
                  description: el.description,
                };
              }),
            }}
            bodyColumns={(fetchSubjectType === 'schoolSubject'
              ? ['nameAndCode', 'assignedTeacherName', 'courseName', 'action']
              : ['nameAndCode', 'assignedTeacherName', 'action']
            ).filter(column => !(readOnly && column === 'action'))}
            dropDownActions={readOnly ? [] : ['edit']}
            idName="subjectId"
            fetchItem={this.fetchSubject}
            deleteItem={this.deleteSubject}
            fetchPageData={this.fetchPageData}
            hidePagination
            isLoading={subjectsFetching}
            renderRowExtra={
              readOnly
                ? null
                : item => (
                    <CustomButton
                      variant="outlined"
                      color="default"
                      size="small"
                      onClick={() => this.openAssignTeacherModal(item)}
                      name={`Assign ${employeeStatic}`}
                    />
                  )
            }
          />
        )}
        {!readOnly && (
          <>
            <SubjectFormModal
              courseId={courseId}
              isModalOpen={isModalOpen}
              formModalCloseProp={this.formModalClose}
              courses={batchCourseList}
              saveSubject={this.saveSubject}
              subject={subject}
              updateSubject={this.updateSubject}
              subjectUpdateSuccess={this.subjectUpdateSuccess}
              subjectCodes={subjectCodes}
              refreshSubjectCodes={() => this.fetchGenSubjectAndCodes(undefined, true)}
              handlePassCourse={cId => this.handleSelectChange({ value: cId })}
              courseSubjects={courseSubjects}
            />
            <AssignTeacherSubjectModal
              isOpen={isAssignTeacherModalOpen}
              subject={assignTeacherSubject}
              allTeachers={employees}
              token={this.props.loggedUserToken}
              onClose={this.closeAssignTeacherModal}
              onSuccess={this.assignTeacherSuccess}
              showWarning={this.showWarning}
            />
          </>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    subjectData: state.subjects.subjectData,
    subjectList: state.subjects.subjectList,
    subject: state.subjects.subject,
    empAssignSubjectList: state.employees.empAssignSubjectList,
    empSubjectList: state.subjects.empSubjectList,
    // Config
    subjectCodes: state.config.subjectCodes,
    // Courses
    batchCourseList: state.courses.batchCourseList,
    courseSubjects: state.subjects.courseSubjects,
    currentBatch: state.batches.currentBatch?.batchId ? state.batches.currentBatch : undefined,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchBatchCourses: data => dispatch(fetchBatchCourseService(data)),
    fetchAllSubjects: data => dispatch(fetchAllSubjectsService(data)),
    saveSubject: data => dispatch(saveSubjectService(data)),
    fetchSubject: data => dispatch(fetchSubjectService(data)),
    updateSubject: data => dispatch(updateSubjectService(data)),
    deleteSubject: data => dispatch(deleteSubjectService(data)),

    // Config
    fetchGenSubjectAndCodes: data => dispatch(fetchGenSubjectAndCodesService(data)),
    // Course subjs
    fetchCourseSubjects: data => dispatch(fetchCourseSubjectsService(data)),
    // Teachers
    fetchAllEmpAssignSubjects: data => dispatch(fetchAllEmpAssignSubjectsService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(SubjectPage);
