import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Label, FormGroup, Row, Col } from 'reactstrap';
// import validator from 'validator';
import CustomButton from '../../../../components/CustomButton';
import { courseStatic } from '../../../../config/constants';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import colors from 'config/colors';
import { formCourseSelectList, formResMessage, infoIconSm } from 'utils/commonFunc';
import SubjectPicker from 'views/admin/Common/SubjectPicker.jsx';
import CommonSelect from 'components/CustomSelect';
import CourseOrSubjectCodeForm from '../../Configuration/CourseOrSubjectCodeForm';
// import { higherCourseSubjects, lowerCourseSubjects } from '../../../../variables/general';

const SubjectFormModal = ({
  isModalOpen,
  formModalCloseProp,
  courses,
  saveSubject,
  subject,
  updateSubject,
  subjectUpdateSuccess,
  subjectCodes,
  refreshSubjectCodes,
  courseId,
  handlePassCourse,
  courseSubjects,
}) => {
  const stateObj = {
    data: {
      course: {},
      subjectList: [],
      // description: '',
      // subjectId: '',
      // name: '',
      // subjectCode: '',
      // status: 'ACTIVE',
    },
    studyLevel: '',
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);
  const [showCreateCode, setShowCreateCode] = useState(false);
  const [subjectSearchText, setSubjectSearchText] = useState('');
  const { data, errors, loading, studyLevel } = stateVal;

  useEffect(() => {
    const setSubjectState = passedList => {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState?.data,
          subjectList: passedList,
        },
      }));
    };
    const existSubs = courseSubjects?.map(el => el.subjectCode);
    if (existSubs?.length) {
      const subList = subjectCodes?.filter(el => existSubs.includes(el.code));
      setSubjectState(
        subList?.map(item => ({
          studyLevel: item.studyLevel,
          label: `${item.name} - (${item.code})`,
          value: item.code,
          name: item.name,
          subjectCode: item.code,
          status: 'ACTIVE',
          isFixed: true,
        }))
      );
    } else {
      setSubjectState([]);
    }
  }, [isModalOpen, courseSubjects, subjectCodes]);

  const courseArr = formCourseSelectList(courses);

  const getSubjectArr = () => {
    const existSubs = courseSubjects?.map(el => el.subjectCode);
    let codes = [];
    if (stateVal?.studyLevel) {
      codes = subjectCodes
        ?.filter(el => ['GENERAL', stateVal.studyLevel].includes(el.studyLevel) && !existSubs.includes(el.code))
        ?.map(item => ({
          studyLevel: item.studyLevel,
          label: `${item.name} - (${item.code})`,
          value: item.code,
          name: item.name,
          subjectCode: item.code,
          status: 'ACTIVE',
        }));
    } else {
      codes = subjectCodes
        ?.filter(el => !existSubs.includes(el.code))
        ?.map(item => ({
          studyLevel: item.studyLevel,
          label: `${item.name} - (${item.code})`,
          value: item.code,
          name: item.name,
          subjectCode: item.code,
          status: 'ACTIVE',
        }));
    }
    return codes;
  };

  const subjectArr = getSubjectArr();
  const fixedSubjects = (data?.subjectList || []).filter(el => el.isFixed);
  // Full pick-list for the checkbox picker: already-assigned subjects (locked/disabled)
  // plus the ones still available to add for this class/study level.
  const subjectOptions = [...fixedSubjects, ...subjectArr];
  const disabledSubjectIds = fixedSubjects.map(el => el.subjectCode);

  useEffect(() => {
    if (subject && Object.keys(subject).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          subjectId: subject.subjectId,
          name: subject.name,
          description: subject.description,
          course: {
            courseId: subject.course.courseId,
            value: subject.course.courseId,
            label: subject.course.name,
          },
          subjectCode: subject.subjectCode,
        },
      }));
    }
  }, [isModalOpen, subject]);

  useEffect(() => {
    const course = courseArr.find(el => el.courseId === courseId);
    if (course) {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          course,
        },
        studyLevel: course.studyLevel,
      }));
    }
  }, [isModalOpen, courseId]);

  // const handleChange = e => {
  //   e.persist();
  //   const { name } = e.target;
  //   const val = e.target.value;
  //   setState(prevState => ({
  //     ...prevState,
  //     data: { ...prevState.data, [name]: val },
  //   }));
  // };

  const handleSelectChange = (name, selectItem) => {
    if (name === 'course') {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          [name]: selectItem || {},
          name: '',
        },
        studyLevel: selectItem?.studyLevel || '',
        //  subjectArr: (selectItem.label.includes('11th') || selectItem.label.includes('12th')) ? higherCourseSubjects : lowerCourseSubjects
      }));
      if (selectItem?.courseId) {
        handlePassCourse(selectItem.courseId);
      }
    } else {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState.data,
          subjectList: selectItem,
          // [name]: selectItem?.label || '',
          // subjectCode: selectItem?.value || '',
        },
      }));
    }
  };

  // Computes the next subjectList off prevState rather than the `subjectList` in scope,
  // so "Select all shown below" - which calls this once per subject, synchronously, before
  // any of them re-render - accumulates correctly instead of each call clobbering the last.
  const toggleSubject = (sub, checked) => {
    setState(prevState => {
      const currentList = prevState.data.subjectList || [];
      const nextList = checked ? [...currentList, sub] : currentList.filter(el => el.subjectCode !== sub.subjectCode);
      return { ...prevState, data: { ...prevState.data, subjectList: nextList } };
    });
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (errors && !Object.keys(errors)?.length) {
      setState(prevState => ({ ...prevState, loading: true }));
      const postData = {
        ...data,
        subjectList: data.subjectList.filter(el => !el?.isFixed),
      };
      if (data?.subjectId) {
        updateSubject(data)
          .then(() => {
            stateReset();
            subjectUpdateSuccess('update');
          })
          .catch(err => setError(err));
      } else if (postData.subjectList?.length) {
        saveSubject(postData)
          .then(() => {
            stateReset();
            subjectUpdateSuccess('add');
          })
          .catch(err => setError(err));
      } else {
        formModalClose();
      }
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (!data.subjectList?.length) {
      errors.subjects = 'Subjects cannot be empty';
    }
    if (!Object.keys(data.course)?.length) {
      errors.course = `${courseStatic} cannot be empty`;
    }
    // if (validator.isEmpty(data.description.toString().trim())) {
    //   errors.description = 'Description cannot be empty';
    // }
    return errors;
  };

  const subjectList = data?.subjectList || [];

  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.subjectId ? 'UPDATE SUBJECT' : 'ASSIGN SUBJECT'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col sm={12} md={12}>
                  <FormGroup>
                    <Label htmlFor="">
                      Select {courseStatic.toLowerCase()}
                      <sup> *</sup>
                    </Label>
                    <CommonSelect
                      name="course"
                      noLabel={true}
                      value={data.course?.value}
                      onChange={(name, value) => {
                        handleSelectChange('course', { value });
                      }}
                      options={courseArr}
                      applyLabelStyle={true}
                      placeholder={`Select ${courseStatic}`}
                      isClearable={true}
                    />
                    {errors.course && <span className="err-msg">{errors.course}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="subjectList">
                      Assign subjects {studyLevel ? `(${studyLevel})` : ''}
                      <sup> *</sup>{' '}
                      {subjectArr?.length > 0 && (
                        <CommonTooltip
                          content={`These are the configured subject name list. It can be assigned to selected ${courseStatic.toLowerCase()}. Showing subjects are only for the Subject-Level: ${studyLevel}`}>
                          {infoIconSm()}
                        </CommonTooltip>
                      )}
                      {!showCreateCode && (
                        <a
                          style={{ marginLeft: 8, fontSize: 13, color: colors.aTag, cursor: 'pointer' }}
                          onClick={() => setShowCreateCode(true)}>
                          + Create new subject code
                        </a>
                      )}
                    </Label>
                    {showCreateCode ? (
                      <CourseOrSubjectCodeForm
                        isShow
                        formFor="showSubjectForm"
                        codeList={subjectCodes}
                        toggleLoading={() => {}}
                        hideForm={() => setShowCreateCode(false)}
                        updateSuccess={() => {
                          setShowCreateCode(false);
                          refreshSubjectCodes && refreshSubjectCodes();
                        }}
                      />
                    ) : !data.course?.courseId ? (
                      <div style={{ fontSize: 12, color: '#9a9a9a', padding: '8px 0' }}>
                        Select {courseStatic.toLowerCase()} above to choose subjects
                      </div>
                    ) : (
                      <SubjectPicker
                        subjectOptions={subjectOptions}
                        searchText={subjectSearchText}
                        onSearchTextChange={setSubjectSearchText}
                        selectedMap={Object.fromEntries(subjectList.map(el => [el.subjectCode, el]))}
                        disabledSubjectIds={disabledSubjectIds}
                        onToggle={toggleSubject}
                        onClearAll={() => handleSelectChange('subjectList', fixedSubjects)}
                      />
                    )}
                    {errors.subjects && <span className="err-msg">{errors.subjects}</span>}
                  </FormGroup>
                  {/* <FormGroup>
                    <Label htmlFor="">
                      Subject code<sup> *</sup>
                    </Label>
                    <Input name="subjectCode" value={data.subjectCode} disabled />
                  </FormGroup> */}
                  {/* <FormGroup>
                    <Label htmlFor="">Description</Label>
                    <Input
                      type="text"
                      name="description"
                      onChange={handleChange}
                      value={data.description}
                      placeholder="Enter here..."
                      maxLength="200"
                    />
                    {errors.description && <span className="err-msg">{errors.description}</span>}
                  </FormGroup> */}
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} name="Save" />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default SubjectFormModal;
