import React from 'react';
import Checkbox from '@material-ui/core/Checkbox';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import Chip from '@material-ui/core/Chip';
import { Label } from 'reactstrap';
import { CommonLoader } from './Loader.jsx';
import colors from 'config/colors.js';
import EmptyState from 'views/admin/Common/EmptyState';

// Shared "pick one or more subjects" widget - same shape as ClassPicker/StudentPicker
// (search box, checkbox list, chip row) so every assignment screen in the app feels the
// same to a non-technical admin instead of some being dropdowns and some being lists.
// Pass `getGroupLabel` to render the list grouped under headers (e.g. by class) - omit it
// for a flat list.
const SubjectPicker = ({
  subjectOptions = [],
  isLoading = false,
  searchText,
  onSearchTextChange,
  selectedMap = {},
  onToggle,
  onClearAll,
  // Subjects that can't be unchecked from here (already assigned and only removable
  // elsewhere) - shown checked but not interactive.
  disabledSubjectIds = [],
  getGroupLabel = null,
  // Field to key rows by - subjects are identified by `subjectCode` when picking from a
  // school's subject catalog, but by `subjectId` when picking from a teacher's own
  // assigned-subjects list (EmpSubjectAssignModal), so this is configurable per caller.
  idKey = 'subjectCode',
}) => {
  const selectedList = Object.values(selectedMap);
  const disabledSet = new Set(disabledSubjectIds);
  const filtered = searchText
    ? subjectOptions.filter(el => el.label?.toLowerCase().includes(searchText.toLowerCase()))
    : subjectOptions;

  const selectAllVisible = () => {
    filtered.forEach(sub => {
      if (!disabledSet.has(sub[idKey]) && !selectedMap[sub[idKey]]) onToggle(sub, true);
    });
  };

  const renderRow = sub => {
    const isDisabled = disabledSet.has(sub[idKey]);
    return (
      <FormControlLabel
        key={sub[idKey]}
        style={{ display: 'flex' }}
        control={
          <Checkbox
            size="small"
            checked={isDisabled || !!selectedMap[sub[idKey]]}
            disabled={isDisabled}
            onChange={e => onToggle(sub, e.target.checked)}
          />
        }
        label={
          <span style={{ fontSize: 13, color: isDisabled ? '#9a9a9a' : undefined }}>
            {sub.label}
            {isDisabled ? ' (already assigned)' : ''}
          </span>
        }
      />
    );
  };

  const renderList = () => {
    if (!filtered?.length) {
      return <EmptyState compact bare icon="fas fa-book" title="No subjects found" />;
    }
    if (!getGroupLabel) {
      return filtered.map(renderRow);
    }
    const groups = [];
    filtered.forEach(sub => {
      const groupLabel = getGroupLabel(sub);
      let group = groups.find(g => g.label === groupLabel);
      if (!group) {
        group = { label: groupLabel, items: [] };
        groups.push(group);
      }
      group.items.push(sub);
    });
    return groups.map((group, i) => (
      <div key={group.label} style={{ marginBottom: 10, marginTop: i === 0 ? 0 : 6 }}>
        <div
          style={{
            fontWeight: 'bold',
            fontSize: 13,
            color: colors.accentDark,
            backgroundColor: '#F5EDFB',
            padding: '5px 10px',
            borderRadius: 5,
            marginBottom: 4,
          }}>
          {group.label}
        </div>
        <div style={{ paddingLeft: 10 }}>{group.items.map(renderRow)}</div>
      </div>
    ));
  };

  return (
    <div>
      <Label htmlFor="">
        Search subjects <sup>*</sup>
      </Label>
      <input
        className="form-control"
        placeholder="Search subjects by name or code"
        value={searchText}
        onChange={e => onSearchTextChange(e.target.value)}
      />

      <div style={{ marginTop: 12, marginBottom: 8 }}>
        <span style={{ fontWeight: 'bold', fontSize: 13, color: '#6b778a' }}>Selected ({selectedList.length}):</span>{' '}
        {selectedList.length ? (
          <>
            {selectedList.map(sub => {
              const isDisabled = disabledSet.has(sub[idKey]);
              return (
                <Chip
                  key={sub[idKey]}
                  size="small"
                  label={sub.label}
                  onDelete={isDisabled ? undefined : () => onToggle(sub, false)}
                  style={isDisabled ? { margin: 2, backgroundColor: '#e0e0e0' } : { margin: 2 }}
                />
              );
            })}
            <span
              onClick={onClearAll}
              style={{ marginLeft: 8, fontSize: 12, color: '#c62828', cursor: 'pointer', textDecoration: 'underline' }}>
              Clear all
            </span>
          </>
        ) : (
          <span style={{ fontSize: 12, color: '#9a9a9a' }}>None yet &mdash; check names below to add them</span>
        )}
      </div>

      <div style={{ marginBottom: 5 }}>
        <span onClick={selectAllVisible} style={{ fontSize: 12, color: '#1565c0', cursor: 'pointer' }}>
          Select all shown below
        </span>
      </div>

      <div style={{ maxHeight: 280, overflowY: 'auto', border: '1px solid #eee', borderRadius: 6, padding: 10 }}>
        {isLoading ? <CommonLoader /> : renderList()}
      </div>
    </div>
  );
};

export default SubjectPicker;
